  "understanding": {
    "purpose": "A compact order-line table linking product variants and charges to warehouse and shipment information.",
    "tasks": [
      "Find an item by ID or SKU and identify its color and size.",
      "Compare quantities, prices, taxes, and totals across rows.",
      "Locate the warehouse and tracking identifier for a line."
    ],
    "relations": [
      "Each row describes one item and its associated financial and fulfillment details.",
      "Color and size qualify the SKU; quantity, price, tax, and total belong together.",
      "Warehouse and tracking identify fulfillment information for the same row."
    ],
    "roles": [
      "The header row names ten fields; no column is declared as a row header.",
      "ID and SKU identify lines and products; the remaining columns describe variants, amounts, and fulfillment."
    ],
    "keep_whole": [
      "Tracking identifiers should remain intact for reliable lookup and copying.",
      "Numeric amounts, quantities, sizes, and color names should remain whole.",
      "SKU and warehouse identifiers are easiest to recognize when kept on one line."
    ],
    "may_wrap": [
      "If space requires it, SKU and warehouse identifiers can wrap at existing hyphens, though this slows scanning.",
      "The fitting layout must also split some unbreakable text, including tracking identifiers."
    ],
    "same_scale": [
      "Keep the short variant and numeric columns compact and broadly comparable in scale.",
      "Give identifier and fulfillment columns more room according to their longer content."
    ],
    "h_vs_v": "A wider table preserves identifiers and short rows but requires horizontal scrolling. Fitting the viewport avoids scrolling at the cost of broken identifiers, taller rows, and slower comparison."
  },
  "designs": [
    {
      "widths": [37, 90, 60, 51, 46, 61, 52, 67, 96, 159],
      "strategy": "Fit exactly within 719px, prioritizing the tracking field while accepting breaks in tracking values, warehouse text, and some other tight cells."
    },
    {
      "widths": [37, 100, 61, 52, 47, 62, 53, 68, 110, 180],
      "strategy": "Use a moderately scrolling 770px table that keeps tracking identifiers whole while allowing SKU and warehouse values to wrap."
    },
    {
      "widths": [37, 157, 61, 52, 47, 62, 53, 68, 143, 180],
